  CONST.forEach(function (c) { c.splice(2, 0, NAMES.el["con." + c[0]] || c[1]); });
  if (typeof window !== "undefined" && window.orosI18n) window.orosI18n.table(NAMES, "sky");
  // Display names in a language (English when the table has none).
  function starName(row, lang) {
    if (!row[3]) return "";
    var T = NAMES[lang] || NAMES.en;
    return T[nameKey(row[3])] || NAMES.en[nameKey(row[3])] || row[3];
  }
  function conName(id, lang) {
    var T = NAMES[lang] || NAMES.en;
    return T["con." + id] || NAMES.en["con." + id] || id;
  }
  var api = { stars: STARS, constellations: CONST, names: NAMES, starName: starName, conName: conName };
